79	+)
80	+
81	+// Archive v3 ships cursor's `store.db` as a JSONL dump of its two tables
82	+// (meta + blobs). Each line is a JSON object carrying one row. Restore
83	+// replays the rows into a fresh SQLite file, so cursor opens the same
84	+// content-addressable DAG it wrote. Plain-text content gives git's pack
85	+// compression something to chew on and keeps per-checkpoint size down
86	+// to a few kB versus ~340 kB for the v2 opaque-base64 format.
87	+const (
88	+	archiveFormat = "cursor-chat-export"
89	+
90	+	// ChatArchiveFilename is the filename used inside a session's metadata
91	+	// directory to carry cursor's JSONL dump. A single archive belongs to
92	+	// exactly one session, so we don't repeat the session id in the name.
93	+	ChatArchiveFilename = "cursor-chat.jsonl"
94	+
95	+	// ChatArchiveFilenameV2 is the legacy opaque-base64 format still readable
96	+	// on restore (the metadata branch may contain pre-v3 checkpoints until
97	+	// they age out).
98	+	ChatArchiveFilenameV2 = ".cursor-chat.json"
99	+)
100	+
101	+// ChatArchive is the v2 archive shape kept around for backward-compatible
102	+// reads of already-pushed checkpoints. New checkpoints use JSONL (v3).
103	+//
104	+// DBPath and TranscriptPath were absolute filesystem paths captured at v2
105	+// export time. v3 export does not populate them (the format is JSONL, not
106	+// this struct). Old archives on the metadata branch may still carry those
107	+// paths until they age out — restore code reads them but never writes them.
108	+type ChatArchive struct {
109	+	Format         string            `json:"format"`
110	+	Version        int               `json:"version"`
111	+	AgentID        string            `json:"agentId"`
112	+	DBPath         string            `json:"db_path,omitempty"`         // legacy v2; never set by v3.
113	+	DBBytes        string            `json:"db_bytes,omitempty"`        // legacy v2; never set by v3.
114	+	DBWALBytes     string            `json:"db_wal_bytes,omitempty"`    // legacy v2; never set by v3.
115	+	DBSHMBytes     string            `json:"db_shm_bytes,omitempty"`    // legacy v2; never set by v3.
116	+	TranscriptPath string            `json:"transcript_path,omitempty"` // legacy v2; never set by v3.
117	+	Transcript     []json.RawMessage `json:"transcript,omitempty"`      // legacy v2; never set by v3.
118	+}
119	+
120	+// jsonlLine is one row in the v3 archive. `t` discriminates meta vs blob;
121	+// other fields apply conditionally. Stored sorted by (t, id) so git pack
122	+// deltas across checkpoints capture only the newly added blob rows.
123	+type jsonlLine struct {
124	+	T    string          `json:"t"`
125	+	K    string          `json:"k,omitempty"`
126	+	V    json.RawMessage `json:"v,omitempty"`
127	+	ID   string          `json:"id,omitempty"`
128	+	Data string          `json:"data,omitempty"`
129	+}
130	+
131	+// ExportChatArchive reads the live cursor store.db for agentID, absorbs any
132	+// pending WAL frames, and returns a JSONL dump of its meta + blobs tables.
133	+// Returns (nil, os.ErrNotExist) if cursor has no DB yet for this agent.
134	+func ExportChatArchive(ctx context.Context, agentID string) ([]byte, error) {
135	+	dbPath, err := findStoreDB(agentID)
136	+	if err != nil {
137	+		return nil, err
138	+	}
139	+
140	+	workDir, err := os.MkdirTemp("", "entire-cursor-export-*")
141	+	if err != nil {
142	+		return nil, fmt.Errorf("temp dir: %w", err)
143	+	}
144	+	defer os.RemoveAll(workDir)
145	+
146	+	stagedPath := filepath.Join(workDir, "store.db")
147	+	if err := copyDBWithSidecars(dbPath, stagedPath); err != nil {
148	+		return nil, fmt.Errorf("staging store.db: %w", err)
149	+	}
150	+
151	+	return dumpJSONL(ctx, stagedPath)
152	+}
153	+
154	+// findStoreDB searches ~/.cursor/chats/*/<agentID>/store.db. Returns
155	+// os.ErrNotExist (wrapped) if cursor hasn't created a DB yet.
156	+func findStoreDB(agentID string) (string, error) {
157	+	home, err := os.UserHomeDir()
158	+	if err != nil {
159	+		return "", fmt.Errorf("home dir: %w", err)
160	+	}
161	+	chatsDir := filepath.Join(home, ".cursor", "chats")
162	+	dbPath, err := findOne(filepath.Join(chatsDir, "*", agentID, "store.db"))
163	+	if err != nil {
164	+		return "", fmt.Errorf("glob store.db: %w", err)
165	+	}
166	+	if dbPath == "" {
167	+		return "", fmt.Errorf("no store.db for agent %q: %w", agentID, os.ErrNotExist)
168	+	}
169	+	return dbPath, nil
170	+}
171	+
172	+// copyDBWithSidecars copies store.db plus its -wal and -shm sidecars into
173	+// dst (dst is the target store.db path). Sidecars get the same stem. The
174	+// copy lets us checkpoint WAL without touching cursor's live files, which
175	+// cursor may still have open.
176	+func copyDBWithSidecars(src, dst string) error {
177	+	if err := copyFile(src, dst); err != nil {
178	+		return err
179	+	}
180	+	for _, suffix := range []string{"-wal", "-shm"} {
181	+		if err := copyFile(src+suffix, dst+suffix); err != nil && !errors.Is(err, os.ErrNotExist) {
182	+			return fmt.Errorf("copying %s: %w", suffix, err)
183	+		}
184	+	}
185	+	return nil
186	+}
187	+
188	+func copyFile(src, dst string) error {
189	+	// Real byte copy, not a hardlink — sqlite's wal_checkpoint(TRUNCATE) and any
190	+	// other writes during dump must not touch cursor's live store.db/-wal/-shm.
191	+	in, err := os.Open(src) //nolint:gosec // cursor-managed path
192	+	if err != nil {
193	+		return fmt.Errorf("open %s: %w", src, err)
194	+	}
195	+	defer in.Close()
196	+	out, err := os.OpenFile(dst, os.O_WRONLY|os.O_CREATE|os.O_TRUNC, 0o600) //nolint:gosec // dst is our own temp path
197	+	if err != nil {
198	+		return fmt.Errorf("create %s: %w", dst, err)
199	+	}
200	+	defer out.Close()
201	+	if _, err := io.Copy(out, in); err != nil {
202	+		return fmt.Errorf("copying bytes: %w", err)
203	+	}
204	+	return nil
205	+}
206	+
207	+// dumpJSONL opens dbPath (a copy), runs wal_checkpoint, and emits JSONL.
208	+func dumpJSONL(ctx context.Context, dbPath string) ([]byte, error) {
209	+	db, err := sql.Open("sqlite", dbPath)
210	+	if err != nil {
211	+		return nil, fmt.Errorf("open sqlite: %w", err)
212	+	}
213	+	defer db.Close()
214	+
215	+	// Consolidate any pending WAL frames into the main DB so our SELECTs see
216	+	// the latest state. TRUNCATE resets the WAL file to size 0 on disk; we
217	+	// discard the copy anyway, but the PRAGMA also makes the DB reads cheaper.
218	+	if _, err := db.ExecContext(ctx, "PRAGMA wal_checkpoint(TRUNCATE);"); err != nil {
219	+		return nil, fmt.Errorf("wal_checkpoint: %w", err)
220	+	}
221	+
222	+	var buf bytes.Buffer
223	+	enc := json.NewEncoder(&buf)
224	+
225	+	if err := writeMetaLines(ctx, db, enc); err != nil {
226	+		return nil, err
227	+	}
228	+	if err := writeBlobLines(ctx, db, enc); err != nil {
229	+		return nil, err
230	+	}
231	+	return buf.Bytes(), nil
232	+}
233	+
234	+func writeMetaLines(ctx context.Context, db *sql.DB, enc *json.Encoder) error {
235	+	rows, err := db.QueryContext(ctx, "SELECT key, value FROM meta ORDER BY key")
236	+	if err != nil {
237	+		return fmt.Errorf("select meta: %w", err)
238	+	}
239	+	defer rows.Close()
240	+	for rows.Next() {
241	+		var key, value string
242	+		if err := rows.Scan(&key, &value); err != nil {
243	+			return fmt.Errorf("scan meta: %w", err)
244	+		}
245	+		// Cursor stores meta.value as hex-encoded ASCII JSON. Decode so the
246	+		// archive is human-readable and redactor-friendly; restore re-encodes.
247	+		decoded, err := hex.DecodeString(value)
248	+		if err != nil {
249	+			return fmt.Errorf("hex-decode meta[%s]: %w", key, err)
250	+		}
251	+		if !json.Valid(decoded) {
252	+			return fmt.Errorf("meta[%s] value is not valid JSON after hex decode", key)
253	+		}
254	+		if err := enc.Encode(jsonlLine{T: "meta", K: key, V: json.RawMessage(decoded)}); err != nil {
255	+			return fmt.Errorf("encode meta line: %w", err)
256	+		}
257	+	}
258	+	if err := rows.Err(); err != nil {
259	+		return fmt.Errorf("iterate meta: %w", err)
260	+	}
261	+	return nil
262	+}
263	+
264	+func writeBlobLines(ctx context.Context, db *sql.DB, enc *json.Encoder) error {
265	+	// Pull rows and sort in Go by id — gives deterministic output regardless
266	+	// of sqlite row ordering and helps git pack dedupe across checkpoints.
267	+	rows, err := db.QueryContext(ctx, "SELECT id, data FROM blobs")
268	+	if err != nil {
269	+		return fmt.Errorf("select blobs: %w", err)
270	+	}
271	+	defer rows.Close()
272	+
273	+	type blobRow struct {
274	+		id   string
275	+		data []byte
276	+	}
277	+	var collected []blobRow
278	+	for rows.Next() {
279	+		var r blobRow
280	+		if err := rows.Scan(&r.id, &r.data); err != nil {
281	+			return fmt.Errorf("scan blob: %w", err)
282	+		}
283	+		collected = append(collected, r)
284	+	}
285	+	if err := rows.Err(); err != nil {
286	+		return fmt.Errorf("iterate blobs: %w", err)
287	+	}
288	+	sort.Slice(collected, func(i, j int) bool { return collected[i].id < collected[j].id })
289	+	for _, r := range collected {
290	+		redacted := redactBlobData(r.data)
291	+		if err := enc.Encode(jsonlLine{
292	+			T:    "blob",
293	+			ID:   r.id,
294	+			Data: base64.StdEncoding.EncodeToString(redacted),
295	+		}); err != nil {
296	+			return fmt.Errorf("encode blob line: %w", err)
297	+		}
298	+	}
299	+	return nil
300	+}
301	+
302	+// redactBlobData strips secrets out of cursor chat-message blobs before they
303	+// go into a checkpoint. Cursor's blobs come in three shapes:
304	+//
305	+//  1. {"role": "...", "content": "<text>"} or content as typed array — chat
306	+//     messages and tool calls. Walk the JSON tree, redacting every string
307	+//     value (covers nested input.contents on tool_use parts).
308	+//  2. Merkle tree nodes — top-level JSON without a "role" key, referencing
309	+//     child blob IDs by content-addressed SHA256. Left untouched so the
310	+//     DAG roundtrips exactly.
311	+//  3. Cursor-wrapped frames (protobuf-like envelope around the inner
312	+//     payload, e.g. user prompts can land in a length-prefixed wire format,
313	+//     and assistant replies sometimes ride inside an encrypted prefix).
314	+//     Not JSON, but the secret-bearing text appears in cleartext within the
315	+//     wrapper. Fall back to redact.Bytes for byte-level scrubbing.
316	+//
317	+// The opaque-archive redaction bypass in the checkpoint walker already keeps
318	+// git from corrupting these on commit; redactBlobData is what gives us the
319	+// chat-content secret scrubbing the bypass would otherwise prevent.
320	+func redactBlobData(data []byte) []byte {
321	+	var doc map[string]any
322	+	if err := json.Unmarshal(data, &doc); err == nil {
323	+		if _, hasRole := doc["role"]; !hasRole {
324	+			return data
325	+		}
326	+		redactJSONStrings(doc)
327	+		out, err := json.Marshal(doc)
328	+		if err != nil {
329	+			return data
330	+		}
331	+		return out
332	+	}
333	+	// Cursor-wrapped binary frame: scrub at the byte level. Slightly less
334	+	// surgical than the JSON walk above (replaces every secret-pattern match
335	+	// in raw bytes, including inside any embedded JSON the wrapper carries)
336	+	// but correct for the user-prompt protobuf frames we observed in the
337	+	// real cursor DB.
338	+	return redact.Bytes(data)
339	+}
340	+
341	+// redactJSONStrings walks v in place and applies redact.String to every
342	+// string value reachable through map values or array elements. Used by
343	+// redactBlobData to scrub chat-message JSON, where any string value is
344	+// potentially user-supplied prompt or tool-call argument content.
345	+func redactJSONStrings(v any) {
346	+	switch value := v.(type) {
347	+	case map[string]any:
348	+		for k, child := range value {
349	+			if s, ok := child.(string); ok {
350	+				value[k] = redact.String(s)
351	+				continue
352	+			}
353	+			redactJSONStrings(child)
354	+		}
355	+	case []any:
356	+		for i, child := range value {
357	+			if s, ok := child.(string); ok {
358	+				value[i] = redact.String(s)
359	+				continue
360	+			}
361	+			redactJSONStrings(child)
362	+		}
363	+	}
364	+}
365	+
366	+// findOne returns the first glob match, or "" if none matched.
367	+func findOne(pattern string) (string, error) {
368	+	matches, err := filepath.Glob(pattern)
369	+	if err != nil {
370	+		return "", fmt.Errorf("glob %s: %w", pattern, err)
371	+	}
372	+	if len(matches) == 0 {
373	+		return "", nil
374	+	}
375	+	return matches[0], nil
376	+}
377	+
378	+// ReadTranscriptFile reads a JSONL transcript file and returns parsed entries.
379	+// Kept exported for any legacy caller; the v3 archive no longer bundles a transcript.
380	+func ReadTranscriptFile(path string) ([]json.RawMessage, error) {
381	+	data, err := os.ReadFile(path) //nolint:gosec // path comes from known cursor dirs
382	+	if err != nil {
383	+		return nil, fmt.Errorf("reading transcript file: %w", err)
384	+	}
385	+	var entries []json.RawMessage
386	+	dec := json.NewDecoder(bytes.NewReader(data))
387	+	for dec.More() {
388	+		var raw json.RawMessage
389	+		if err := dec.Decode(&raw); err != nil {
390	+			return nil, fmt.Errorf("decoding transcript line: %w", err)
391	+		}
392	+		entries = append(entries, raw)
393	+	}
394	+	return entries, nil
395	+}
