424	+// seedStoreDB creates a real cursor-format SQLite store.db under
425	+// $HOME/.cursor/chats/<workspace>/<testAgentID>/ with the given meta + blobs.
426	+// Returns the path to store.db so callers can chmod it for read-only tests.
427	+func seedStoreDB(t *testing.T, home string, metaValue []byte, blobs map[string][]byte) string {
428	+	t.Helper()
429	+	dbDir := filepath.Join(home, ".cursor", "chats", testWorkspace, testAgentID)
430	+	if err := os.MkdirAll(dbDir, 0o755); err != nil {
431	+		t.Fatalf("mkdir chats: %v", err)
432	+	}
433	+	dbPath := filepath.Join(dbDir, "store.db")
434	+
435	+	db, err := sql.Open("sqlite", dbPath)
436	+	if err != nil {
437	+		t.Fatalf("open seed db: %v", err)
438	+	}
439	+	t.Cleanup(func() { _ = db.Close() })
440	+
441	+	if _, err := db.ExecContext(context.Background(),`
442	+		CREATE TABLE meta  (key TEXT PRIMARY KEY, value TEXT);
443	+		CREATE TABLE blobs (id  TEXT PRIMARY KEY, data BLOB);
444	+	`); err != nil {
445	+		t.Fatalf("create tables: %v", err)
446	+	}
447	+	if metaValue != nil {
448	+		// Cursor stores meta.value as hex-ASCII of the JSON bytes.
449	+		if _, err := db.ExecContext(context.Background(),"INSERT INTO meta(key, value) VALUES('0', ?)", hex.EncodeToString(metaValue)); err != nil {
450	+			t.Fatalf("insert meta: %v", err)
451	+		}
452	+	}
453	+	for id, data := range blobs {
454	+		if _, err := db.ExecContext(context.Background(),"INSERT INTO blobs(id, data) VALUES(?, ?)", id, data); err != nil {
