464	+// parseArchiveLines reads the JSONL export and splits it into meta + blob rows.
465	+func parseArchiveLines(t *testing.T, data []byte) (metas []jsonlLine, blobs []jsonlLine) {
466	+	t.Helper()
467	+	scanner := bufio.NewScanner(bytes.NewReader(data))
468	+	scanner.Buffer(make([]byte, 0, 64*1024), 8*1024*1024)
469	+	for scanner.Scan() {
470	+		var l jsonlLine
471	+		if err := json.Unmarshal(scanner.Bytes(), &l); err != nil {
472	+			t.Fatalf("unmarshal line %q: %v", scanner.Text(), err)
473	+		}
474	+		switch l.T {
475	+		case "meta":
476	+			metas = append(metas, l)
477	+		case "blob":
478	+			blobs = append(blobs, l)
479	+		default:
480	+			t.Fatalf("unexpected row type %q", l.T)
481	+		}
482	+	}
483	+	if err := scanner.Err(); err != nil {
484	+		t.Fatalf("scan: %v", err)
485	+	}
486	+	return metas, blobs
487	+}
