514	+		t.Errorf("meta.v is not valid JSON: %s", metas[0].V)
515	+	}
516	+	if !bytes.Equal([]byte(metas[0].V), metaJSON) {
517	+		t.Errorf("meta.v = %s, want %s", metas[0].V, metaJSON)
518	+	}
519	+	if len(blobs) != len(blobBytes) {
520	+		t.Fatalf("blob rows = %d, want %d", len(blobs), len(blobBytes))
521	+	}
522	+	for _, b := range blobs {
523	+		want, ok := blobBytes[b.ID]
524	+		if !ok {
525	+			t.Errorf("unexpected blob id %q", b.ID)
526	+			continue
527	+		}
528	+		got, err := base64.StdEncoding.DecodeString(b.Data)
529	+		if err != nil {
530	+			t.Errorf("decode blob %s: %v", b.ID, err)
531	+			continue
532	+		}
533	+		// Cursor chat-message blobs go through secret redaction, which round-trips
534	+		// the JSON via Marshal and may reorder keys. Compare structurally instead
535	+		// of byte-equal.
536	+		var gotDoc, wantDoc any
537	+		if uerr := json.Unmarshal(got, &gotDoc); uerr != nil {
538	+			t.Errorf("blob %s decoded bytes are not JSON: %v", b.ID, uerr)
539	+			continue
540	+		}
541	+		if uerr := json.Unmarshal(want, &wantDoc); uerr != nil {
542	+			t.Errorf("blob %s seed bytes are not JSON: %v", b.ID, uerr)
543	+			continue
544	+		}
545	+		if !reflect.DeepEqual(gotDoc, wantDoc) {
546	+			t.Errorf("blob %s roundtrip mismatch:\n got:  %s\n want: %s", b.ID, got, want)
547	+		}
548	+	}
549	+}
