551	+func TestExportChatArchive_RedactsBlobContent(t *testing.T) {
552	+	// Cursor chat blobs may carry user-pasted secrets in their content fields.
553	+	// The export pipeline must run them through the same redactor the main
554	+	// transcript uses; cursor.go's redactBlobData targets {role, content} JSON
555	+	// shapes (string and array variants) and leaves merkle tree nodes alone.
556	+	tmp := t.TempDir()
557	+	t.Setenv("HOME", tmp)
