559	+	// High-entropy token shaped like a typical OpenAI/Anthropic API key — the
560	+	// AKIA-style AWS test key has too little entropy to trip the threshold.
561	+	secret := "REDACTED"
562	+	stringContent := []byte(`{"role":"user","content":"key=` + secret + `"}`)
563	+	arrayContent := []byte(`{"role":"assistant","content":[{"type":"text","text":"token: ` + secret + `"}]}`)
564	+	// Tool-use shape: secret hides inside a nested input object. A top-level-only
565	+	// redactor would miss this — recursive walk must catch it.
566	+	toolUseContent := []byte(`{"role":"assistant","content":[{"type":"tool_use","name":"Write","input":{"path":"foo.txt","contents":"# api: ` + secret + `"}}]}`)
567	+	// Cursor-wrapped binary frame: real cursor DBs put user prompts inside a
568	+	// protobuf-like envelope. The bytes aren't JSON but the secret is in the
569	+	// clear. Falls through to redact.Bytes byte-level scrubbing.
570	+	wrappedFrame := append([]byte{0x0a, 0x8a, 0x01}, []byte("user input: "+secret+" trailing")...)
571	+	treeNode := []byte(`{"latestRootBlobId":"958e728654e1e5e7b019e874d9045f53ba89b36af97e785f023ea8963e961c45"}`)
572	+
573	+	seedStoreDB(t, tmp, []byte(`{"agentId":"x"}`), map[string][]byte{
574	+		"chat-string":     stringContent,
575	+		"chat-array":      arrayContent,
576	+		"chat-tool-use":   toolUseContent,
577	+		"wrapped-binary":  wrappedFrame,
578	+		"tree-node":       treeNode,
579	+	})
580	+
581	+	data, err := ExportChatArchive(context.Background(), testAgentID)
582	+	if err != nil {
583	+		t.Fatalf("ExportChatArchive: %v", err)
584	+	}
585	+	_, blobs := parseArchiveLines(t, data)
586	+
587	+	for _, b := range blobs {
588	+		raw, err := base64.StdEncoding.DecodeString(b.Data)
589	+		if err != nil {
590	+			t.Fatalf("decode %s: %v", b.ID, err)
591	+		}
592	+		if b.ID == "tree-node" {
593	+			if !bytes.Equal(raw, treeNode) {
594	+				t.Errorf("tree node bytes mutated by redaction:\n got:  %s\n want: %s", raw, treeNode)
595	+			}
596	+			continue
597	+		}
598	+		if bytes.Contains(raw, []byte(secret)) {
599	+			t.Errorf("blob %s leaked secret %q after redaction:\n%s", b.ID, secret, raw)
600	+		}

600	+		}
601	+		if !bytes.Contains(raw, []byte("REDACTED")) {
602	+			t.Errorf("blob %s expected REDACTED placeholder after redaction:\n%s", b.ID, raw)
603	+		}
