741	+// WorkspaceHash returns the Cursor workspace hash for a project path.
742	+// Cursor stores per-project chat DBs under MD5(absolute_project_path).
743	+func WorkspaceHash(projectPath string) string {
744	+	sum := md5.Sum([]byte(projectPath)) //nolint:gosec // matches Cursor's convention
745	+	return hex.EncodeToString(sum[:])
746	+}
747	+
748	+// WorkspaceSlug returns the Cursor project slug for a project path.
749	+// Cursor stores per-project transcript JSONLs under a slug derived by stripping
750	+// the leading slash and replacing every non-alphanumeric character with a dash
751	+// (e.g. dots and underscores too — not just slashes). Delegates to the same
752	+// helper cursor's own session-dir resolver uses, so write paths stay aligned
753	+// with cursor's read paths even when the workspace path contains "." or "_".
754	+func WorkspaceSlug(projectPath string) string {
755	+	return sanitizePathForCursor(projectPath)
756	+}
757	+
758	+// RestoreCheckpointFiles rebuilds cursor's store.db for this session from the
759	+// checkpoint's agent-contributed extras. Supports two archive shapes:
760	+//
761	+//   - v3 (current): cursor-chat.jsonl — JSONL dump of meta + blobs tables.
762	+//     Restore replays the rows into a fresh SQLite file.
763	+//   - v2 (legacy, still present on already-pushed checkpoints):
764	+//     <sessionID>.cursor-chat.json — opaque base64 of store.db + WAL + SHM.
765	+//
766	+// The workspace hash is computed from the current working directory,
767	+// matching Cursor's own MD5(project_path) convention — run rewind/resume
768	+// from the repo that originally hosted the session.
769	+func (c *CursorAgent) RestoreCheckpointFiles(ctx context.Context, sessionID string, files map[string][]byte) error {
770	+	target, err := cursorTargetPaths(sessionID)
771	+	if err != nil {
772	+		return err
773	+	}
774	+
775	+	if data, ok := files[ChatArchiveFilename]; ok {
776	+		return restoreV3(ctx, target, data)
777	+	}
778	+	if data, ok := files[sessionID+ChatArchiveFilenameV2]; ok {
779	+		return restoreV2(target, data)
780	+	}
781	+	return nil
782	+}
