784	+// cursorTarget holds the paths we write into for a given session.
785	+type cursorTarget struct {
786	+	agentID   string
787	+	storeDB   string // ~/.cursor/chats/<hash>/<agent-id>/store.db
788	+	nestedJSO string // ~/.cursor/projects/<slug>/agent-transcripts/<agent-id>/<agent-id>.jsonl
789	+}
