791	+// cursorTargetPaths resolves cursor's on-disk layout for the current cwd.
792	+// Cursor resolves symlinks when computing its workspace hash (e.g. /tmp → /private/tmp
793	+// on macOS), so we match that before hashing/slugifying.
794	+func cursorTargetPaths(sessionID string) (cursorTarget, error) {
795	+	home, err := os.UserHomeDir()
796	+	if err != nil {
797	+		return cursorTarget{}, fmt.Errorf("home directory: %w", err)
798	+	}
799	+	cwd, err := os.Getwd() //nolint:forbidigo // Cursor's MD5(project_path) uses cwd, not git root
800	+	if err != nil {
801	+		return cursorTarget{}, fmt.Errorf("current directory: %w", err)
802	+	}
803	+	if resolved, evalErr := filepath.EvalSymlinks(cwd); evalErr == nil {
804	+		cwd = resolved
805	+	}
806	+	hash := WorkspaceHash(cwd)
807	+	slug := WorkspaceSlug(cwd)
808	+	return cursorTarget{
809	+		agentID:   sessionID,
810	+		storeDB:   filepath.Join(home, ".cursor", "chats", hash, sessionID, "store.db"),
811	+		nestedJSO: filepath.Join(home, ".cursor", "projects", slug, "agent-transcripts", sessionID, sessionID+".jsonl"),
812	+	}, nil
813	+}
