815	+// restoreV3 rebuilds store.db from a JSONL dump.
816	+func restoreV3(ctx context.Context, t cursorTarget, data []byte) error {
817	+	if err := os.MkdirAll(filepath.Dir(t.storeDB), 0o750); err != nil {
818	+		return fmt.Errorf("chats dir: %w", err)
819	+	}
820	+	// Remove any prior DB + sidecars so sqlite creates a fresh file with no
821	+	// WAL state bleeding through from a stale session.
822	+	for _, p := range []string{t.storeDB, t.storeDB + "-wal", t.storeDB + "-shm"} {
823	+		if err := os.Remove(p); err != nil && !os.IsNotExist(err) {
824	+			return fmt.Errorf("clearing %s: %w", filepath.Base(p), err)
825	+		}
826	+	}
827	+
828	+	db, err := sql.Open("sqlite", t.storeDB)
829	+	if err != nil {
830	+		return fmt.Errorf("open sqlite: %w", err)
831	+	}
832	+	defer db.Close()
833	+
834	+	// Force DELETE journal mode so all writes land in the main DB file,
835	+	// not in a WAL sidecar. Without this modernc.org/sqlite defaults to WAL
836	+	// mode; rows would sit in store.db-wal and other SQLite clients (e.g.
837	+	// cursor-agent itself) may fail to read them back when the main file is
838	+	// still the initial empty page.
839	+	if _, err := db.ExecContext(ctx, "PRAGMA journal_mode=DELETE;"); err != nil {
840	+		return fmt.Errorf("set journal_mode: %w", err)
841	+	}
842	+
843	+	if _, err := db.ExecContext(ctx, `
844	+		CREATE TABLE meta  (key TEXT PRIMARY KEY, value TEXT);
845	+		CREATE TABLE blobs (id  TEXT PRIMARY KEY, data BLOB);
846	+	`); err != nil {
847	+		return fmt.Errorf("create tables: %w", err)
848	+	}
849	+
850	+	tx, err := db.BeginTx(ctx, nil)
851	+	if err != nil {
852	+		return fmt.Errorf("begin: %w", err)
853	+	}
854	+	defer tx.Rollback() //nolint:errcheck // Commit() supersedes
855	+
856	+	scanner := bufio.NewScanner(bytes.NewReader(data))
857	+	// Blobs can be larger than bufio.Scanner's default 64 KB line cap.
858	+	// SQLite row size is effectively unbounded for our inputs; 8 MB is
859	+	// comfortably above any single cursor blob we expect.
860	+	scanner.Buffer(make([]byte, 0, 64*1024), 8*1024*1024)
861	+
862	+	lineNum := 0
863	+	for scanner.Scan() {
864	+		lineNum++
865	+		line := scanner.Bytes()
866	+		if len(bytes.TrimSpace(line)) == 0 {
867	+			continue
868	+		}
869	+		var row jsonlLine
870	+		if err := json.Unmarshal(line, &row); err != nil {
871	+			return fmt.Errorf("parse line %d: %w", lineNum, err)
872	+		}
873	+		switch row.T {
874	+		case "meta":
875	+			if err := insertMetaRow(ctx, tx, row); err != nil {
876	+				return fmt.Errorf("line %d: %w", lineNum, err)
877	+			}
878	+		case "blob":
879	+			if err := insertBlobRow(ctx, tx, row); err != nil {
880	+				return fmt.Errorf("line %d: %w", lineNum, err)
881	+			}
882	+		default:
883	+			return fmt.Errorf("line %d: unknown row type %q", lineNum, row.T)
884	+		}
885	+	}
886	+	if err := scanner.Err(); err != nil {
887	+		return fmt.Errorf("read archive: %w", err)
888	+	}
889	+	if err := tx.Commit(); err != nil {
890	+		return fmt.Errorf("commit: %w", err)
891	+	}
892	+	return nil
893	+}
