895	+func insertMetaRow(ctx context.Context, tx *sql.Tx, row jsonlLine) error {
896	+	// Cursor's meta.value is stored as hex-ASCII of the JSON bytes; preserve
897	+	// that shape so cursor reads the same format it wrote.
898	+	if len(row.V) == 0 {
899	+		return errors.New("meta row missing v")
900	+	}
901	+	if _, err := tx.ExecContext(ctx,
902	+		"INSERT INTO meta(key, value) VALUES(?, ?)",
903	+		row.K, hex.EncodeToString(row.V),
904	+	); err != nil {
905	+		return fmt.Errorf("insert meta: %w", err)
906	+	}
907	+	return nil
908	+}
909	+
910	+func insertBlobRow(ctx context.Context, tx *sql.Tx, row jsonlLine) error {
911	+	raw, err := base64.StdEncoding.DecodeString(row.Data)
912	+	if err != nil {
913	+		return fmt.Errorf("decode blob data: %w", err)
914	+	}
915	+	if _, err := tx.ExecContext(ctx,
916	+		"INSERT INTO blobs(id, data) VALUES(?, ?)",
917	+		row.ID, raw,
918	+	); err != nil {
919	+		return fmt.Errorf("insert blob: %w", err)
920	+	}
921	+	return nil
922	+}
