924	+// restoreV2 keeps the legacy opaque-base64 restore path alive for already-
925	+// pushed checkpoints that predate v3. When the metadata branch ages out
926	+// past the last v2 checkpoint, this function and ChatArchive can be removed.
927	+func restoreV2(t cursorTarget, data []byte) error {
928	+	var archive ChatArchive
929	+	if err := json.Unmarshal(data, &archive); err != nil {
930	+		return fmt.Errorf("decoding v2 cursor archive: %w", err)
931	+	}
932	+	if archive.Format != archiveFormat {
933	+		return fmt.Errorf("unexpected v2 archive format %q", archive.Format)
934	+	}
935	+	if archive.Version != 2 {
936	+		return fmt.Errorf("unsupported v2 archive version %d", archive.Version)
937	+	}
938	+
939	+	if err := os.MkdirAll(filepath.Dir(t.storeDB), 0o750); err != nil {
940	+		return fmt.Errorf("creating chats directory: %w", err)
941	+	}
942	+	if err := writeBase64(archive.DBBytes, t.storeDB); err != nil {
943	+		return fmt.Errorf("writing store.db: %w", err)
944	+	}
945	+	for _, pair := range []struct {
946	+		b64, path string
947	+	}{
948	+		{archive.DBWALBytes, t.storeDB + "-wal"},
949	+		{archive.DBSHMBytes, t.storeDB + "-shm"},
950	+	} {
951	+		if pair.b64 == "" {
952	+			_ = os.Remove(pair.path)
953	+			continue
954	+		}
955	+		if err := writeBase64(pair.b64, pair.path); err != nil {
956	+			return fmt.Errorf("writing %s: %w", filepath.Base(pair.path), err)
957	+		}
958	+	}
959	+
960	+	if len(archive.Transcript) > 0 {
961	+		if err := os.MkdirAll(filepath.Dir(t.nestedJSO), 0o750); err != nil {
962	+			return fmt.Errorf("creating transcripts directory: %w", err)
963	+		}
964	+		if err := writeTranscript(archive.Transcript, t.nestedJSO); err != nil {
965	+			return fmt.Errorf("writing transcript: %w", err)
966	+		}
967	+	}
968	+	return nil
969	+}
970	+
971	+func writeBase64(b64, targetPath string) error {
972	+	raw, err := base64.StdEncoding.DecodeString(b64)
973	+	if err != nil {
974	+		return fmt.Errorf("base64: %w", err)
975	+	}
976	+	if err := os.WriteFile(targetPath, raw, 0o600); err != nil {
977	+		return fmt.Errorf("write %s: %w", targetPath, err)
978	+	}
979	+	return nil
980	+}
981	+
982	+func writeTranscript(entries []json.RawMessage, targetPath string) error {
983	+	f, err := os.OpenFile(targetPath, os.O_WRONLY|os.O_CREATE|os.O_TRUNC, 0o600) //nolint:gosec // path under ~/.cursor
984	+	if err != nil {
985	+		return fmt.Errorf("open: %w", err)
986	+	}
987	+	defer f.Close()
988	+	for _, entry := range entries {
989	+		if _, err := f.Write(entry); err != nil {
990	+			return fmt.Errorf("write entry: %w", err)
991	+		}
992	+		if _, err := f.WriteString("\n"); err != nil {
993	+			return fmt.Errorf("write newline: %w", err)
994	+		}
995	+	}
996	+	return nil
997	+}
