1943	+// contributeLiveExtras invokes every registered CheckpointContributor to refresh
1944	+// its archive files in the session metadata dir, then reads those files back
1945	+// into a map suitable for ExtraFiles. We iterate all contributors rather than
1946	+// just state.AgentType because multiple agents can share a session_id (for
1947	+// example when a repo enables both cursor and claude-code hooks, claude-code's
1948	+// session-start can overwrite agent_type in state even though cursor-agent is
1949	+// the one actually writing to ~/.cursor/chats/<id>/store.db). Contributors
1950	+// that have no data for this session are expected to return wrapped
1951	+// os.ErrNotExist, which we treat as a silent no-op.
1952	+func contributeLiveExtras(ctx context.Context, sessionID string) (map[string][]byte, error) {
1953	+	worktreeRoot, err := paths.WorktreeRoot(ctx)
1954	+	if err != nil {
1955	+		return map[string][]byte{}, fmt.Errorf("worktree root: %w", err)
1956	+	}
1957	+	metadataDirAbs := filepath.Join(worktreeRoot, paths.SessionMetadataDirFromSessionID(sessionID))
1958	+	if mkErr := os.MkdirAll(metadataDirAbs, 0o750); mkErr != nil {
1959	+		return map[string][]byte{}, fmt.Errorf("ensure metadata dir: %w", mkErr)
1960	+	}
1961	+
1962	+	for _, name := range agent.List() {
1963	+		ag, getErr := agent.Get(name)
1964	+		if getErr != nil {
1965	+			continue
1966	+		}
1967	+		contributor, ok := ag.(agent.CheckpointContributor)
1968	+		if !ok {
1969	+			continue
1970	+		}
1971	+		if err := contributor.ContributeCheckpointFiles(ctx, sessionID, metadataDirAbs); err != nil && !errors.Is(err, os.ErrNotExist) {
1972	+			logging.Debug(logging.WithComponent(ctx, "checkpoint"), "live extras contributor failed",
1973	+				slog.String("session_id", sessionID),
1974	+				slog.String("agent", string(name)),
1975	+				slog.String("error", err.Error()),
1976	+			)
1977	+		}
1978	+	}
1979	+
1980	+	entries, err := os.ReadDir(metadataDirAbs)
1981	+	if err != nil {
1982	+		return map[string][]byte{}, fmt.Errorf("read metadata dir: %w", err)
1983	+	}
1984	+	extras := map[string][]byte{}
1985	+	for _, e := range entries {
1986	+		if e.IsDir() || standardMetadataFiles[e.Name()] {
1987	+			continue
1988	+		}
1989	+		content, readErr := os.ReadFile(filepath.Join(metadataDirAbs, e.Name())) //nolint:gosec // our own metadata dir
1990	+		if readErr != nil {
1991	+			return map[string][]byte{}, fmt.Errorf("read %s: %w", e.Name(), readErr)
1992	+		}
1993	+		extras[e.Name()] = content
1994	+	}
1995	+	return extras, nil
1996	+}
